-- Research entities are independent of the species-index projection.
CREATE TABLE source_revisions(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id),version TEXT NOT NULL,retrieved TEXT NOT NULL,sha256 TEXT NOT NULL,UNIQUE(source_id,version,sha256));
CREATE TABLE taxa(id TEXT PRIMARY KEY,rank TEXT NOT NULL,canonical_name TEXT NOT NULL);
CREATE TABLE taxon_names(id TEXT PRIMARY KEY,taxon_id TEXT REFERENCES taxa(id),name TEXT NOT NULL,authors TEXT NOT NULL,status TEXT NOT NULL,accepted_name_id TEXT,revision_id TEXT NOT NULL REFERENCES source_revisions(id),raw_json TEXT NOT NULL,UNIQUE(id,revision_id));
CREATE TABLE taxonomic_assertions(id INTEGER PRIMARY KEY,taxon_id TEXT NOT NULL REFERENCES taxa(id),predicate TEXT NOT NULL,value TEXT NOT NULL,source_id TEXT REFERENCES sources(id),revision_id TEXT REFERENCES source_revisions(id),status TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '');
CREATE TABLE cultivars(id TEXT PRIMARY KEY,name TEXT NOT NULL,source_id TEXT REFERENCES sources(id),registry_accepted INTEGER CHECK(registry_accepted IN(0,1)),registry_established INTEGER CHECK(registry_established IN(0,1)),parentage_verbatim TEXT,notes TEXT NOT NULL DEFAULT '');
CREATE TABLE accessions(id TEXT PRIMARY KEY,label TEXT NOT NULL,taxon_id TEXT REFERENCES taxa(id),cultivar_id TEXT REFERENCES cultivars(id),identity_status TEXT NOT NULL DEFAULT 'unverified',provenance TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cross_plans(id TEXT PRIMARY KEY,maternal_accession_id TEXT NOT NULL REFERENCES accessions(id),paternal_accession_id TEXT NOT NULL REFERENCES accessions(id),hypothesis TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE pollen_lots(id TEXT PRIMARY KEY,accession_id TEXT NOT NULL REFERENCES accessions(id),collected_on TEXT,storage_protocol TEXT NOT NULL DEFAULT '');
CREATE TABLE pollination_attempts(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES cross_plans(id),attempted_on TEXT NOT NULL,maternal_inflorescence TEXT,pollen_lot_id TEXT REFERENCES pollen_lots(id),protocol TEXT NOT NULL DEFAULT '',controls TEXT NOT NULL DEFAULT '',followup_cutoff TEXT,censored INTEGER NOT NULL DEFAULT 1 CHECK(censored IN(0,1)));
CREATE TABLE outcomes(id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL REFERENCES pollination_attempts(id),stage TEXT NOT NULL CHECK(stage IN('fruit set','seed harvested','germination','seedling survival','flowering','fertility assessed')),observed_on TEXT NOT NULL,result TEXT NOT NULL CHECK(result IN('observed','not observed','unknown')),numerator INTEGER CHECK(numerator>=0),denominator INTEGER CHECK(denominator>0),denominator_unit TEXT,CHECK (numerator IS NULL OR denominator IS NULL OR numerator<=denominator),CHECK(denominator IS NULL OR denominator_unit IS NOT NULL));
CREATE TABLE evidence_claims(id TEXT PRIMARY KEY,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,claim TEXT NOT NULL,evidence_type TEXT NOT NULL CHECK(evidence_type IN('published-cross','registrar-record','breeder-report','user-observation','inferred-affinity','unknown')),source_id TEXT REFERENCES sources(id),revision_id TEXT REFERENCES source_revisions(id),locator TEXT NOT NULL DEFAULT '',uncertainty TEXT NOT NULL,conflicts_with TEXT REFERENCES evidence_claims(id),CHECK(evidence_type='user-observation' OR source_id IS NOT NULL));
CREATE TABLE genomic_measurements(id TEXT PRIMARY KEY,accession_id TEXT NOT NULL REFERENCES accessions(id),measurement_type TEXT NOT NULL CHECK(measurement_type IN('chromosome count','ploidy','genome size')),value REAL,unit TEXT,method TEXT,source_id TEXT REFERENCES sources(id),uncertainty TEXT NOT NULL,CHECK(value IS NULL OR (unit IS NOT NULL AND source_id IS NOT NULL)));
CREATE TABLE pedigree_edges(child_accession_id TEXT NOT NULL REFERENCES accessions(id),parent_accession_id TEXT NOT NULL REFERENCES accessions(id),role TEXT NOT NULL CHECK(role IN('maternal','paternal','unknown')),attempt_id TEXT REFERENCES pollination_attempts(id),claim_id TEXT NOT NULL REFERENCES evidence_claims(id),PRIMARY KEY(child_accession_id,parent_accession_id,role),CHECK(child_accession_id<>parent_accession_id));
CREATE TRIGGER prevent_pedigree_cycle BEFORE INSERT ON pedigree_edges BEGIN
 SELECT CASE WHEN EXISTS(WITH RECURSIVE ancestors(id) AS (SELECT NEW.parent_accession_id UNION SELECT p.parent_accession_id FROM pedigree_edges p JOIN ancestors a ON p.child_accession_id=a.id) SELECT 1 FROM ancestors WHERE id=NEW.child_accession_id) THEN RAISE(ABORT,'Pedigree cycle rejected') END;
END;
CREATE TRIGGER prevent_pedigree_update BEFORE UPDATE ON pedigree_edges BEGIN SELECT RAISE(ABORT,'Pedigree edges are immutable; delete and reinsert with reviewed claim'); END;
CREATE INDEX names_taxon ON taxon_names(taxon_id);
CREATE INDEX claims_subject ON evidence_claims(subject_type,subject_id);
CREATE INDEX attempts_plan ON pollination_attempts(plan_id);
CREATE INDEX outcomes_attempt ON outcomes(attempt_id);
CREATE INDEX pedigree_child ON pedigree_edges(child_accession_id);
